def P(n):
    C = 8257457600
    return n**3 - C

n_values = [2021, 2022, 2023]
for n in n_values:
    p_n = P(n)
    import math
    if p_n < 0:
        print(f"P({n}) = {p_n}, Negative, Not a square.")
    else:
        root = math.isqrt(p_n)
        is_square = root * root == p_n
        print(f"P({n}) = {p_n}, Root={root}, Is square? {is_square}")

